mapper.select:
SELECT p.post_id AS postId, p.member_id AS memberId, m.nickname AS nickname, m.profile_image_url AS profileImageUrl, p.topic AS topic, p.content AS content, p.language AS language, p.content_version AS contentVersion, p.created_at AS createdAt, p.updated_at AS updatedAt FROM community_posts p INNER JOIN members m ON p.member_id = m.member_id
WHERE ( p.created_at < #{cursorCreatedAt} OR ( p.created_at = #{cursorCreatedAt} AND p.post_id < #{cursorPostId} ) )
ORDER BY p.created_at DESC, p.post_id DESC LIMIT #{size}
